#!/usr/bin/env node
/**
 * Landing lane-consistency guard.
 *
 * The landing renders the lanes in TWO places, and they are independent data:
 *
 *   1. the hero demo — `.bk[data-t]` buckets, fed by `var mails` (samples) and
 *      `var totals` (final counts)
 *   2. the interactive replica below it — its own `var TIERS` array, fed by
 *      `var mail` with a `t:` field
 *
 * Nothing in CI could see a mismatch between them. `check-website-lockstep.sh`
 * compares EN/KO *structure* (ids, media, class definitions) and passes.
 * `check-lane-identity.mjs` covers `packages/web`, not `website/`.
 *
 * It has already shipped twice in one day:
 *
 *   - #1242 rebuilt the hero buckets for five lanes and re-tagged the samples
 *     feeding them — in English only. The Korean patch used unasserted string
 *     replacement against English anchors, so three substitutions silently did
 *     nothing. Two KO samples kept a `'auto'` tag whose bucket no longer
 *     existed. The animation does `var c = cells[m[2]]; c.box.…`, which threw
 *     inside a setTimeout: page fine, nothing logged, counter frozen on the
 *     first screen a Korean visitor sees.
 *   - the replica was simply never updated, and served
 *     `{ id: 'auto', blurb: 'Handled without you' }` — the caption
 *     product-vocabulary.md explicitly forbids — long after AUTO was retired.
 *
 * Both were data mismatches, not markup drift, which is exactly the shape the
 * existing guards cannot see. Hence this one.
 *
 * Source of truth is the API's TIERS list, same as check-lane-identity.mjs.
 * AUTO and CALL are retired v1 values: the app still renders them for pre-flip
 * rows, but the marketing site must never present one as a live lane.
 */

import { readdirSync, readFileSync } from "node:fs";

const TIERS_FILE = "packages/api/src/judge/tiers.ts";

/**
 * Every landing, discovered rather than listed. #1240 shipped five more
 * languages the day this guard was written, generated by substituting into a
 * stale copy of the English page — so all five went live with an AUTO bucket
 * and a four-tier compare table. A hardcoded pair would not have seen any of
 * it, and would not see the next language either.
 *
 * A landing is `website/index.html` or any `website/<two-letter>/index.html`.
 * Every one of them must carry a lane surface: the six-section landing (P11b)
 * renders the lanes as a `.lane-list`, the older one as a hero demo plus a
 * replica. A landing with neither is a failure, not a skip — otherwise moving
 * the markup would turn this guard into a silent pass over zero pages.
 */
const LANDINGS = ["website/index.html", ...readdirSync("website", { withFileTypes: true })
  .filter((e) => e.isDirectory() && /^[a-z]{2}$/.test(e.name))
  .map((e) => `website/${e.name}/index.html`)]
  .filter((f) => {
    try {
      readFileSync(f, "utf8");
      return true;
    } catch {
      return false;
    }
  });

/** Retired v1 values. Legal in stored data, never on the landing. */
const RETIRED = new Set(["auto", "call"]);

const problems = [];

/** Live lanes, from the API's TIERS minus the retired ones. */
function liveLanes() {
  const src = readFileSync(TIERS_FILE, "utf8");
  const m = src.match(/export const TIERS = \[(.*?)\] as const;/s);
  if (!m) {
    console.error(`✗ could not read TIERS from ${TIERS_FILE}`);
    process.exit(1);
  }
  return [...m[1].matchAll(/"([A-Z]+)"/g)]
    .map((x) => x[1].toLowerCase())
    .filter((t) => !RETIRED.has(t));
}

/** `[...]` after `needle`, brace-matched so nested arrays do not truncate it. */
function arrayAfter(src, needle) {
  const at = src.indexOf(needle);
  if (at < 0) return null;
  const open = src.indexOf("[", at);
  if (open < 0) return null;
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    if (src[i] === "[") depth++;
    else if (src[i] === "]" && --depth === 0) return src.slice(open, i + 1);
  }
  return null;
}

/**
 * The six-section landing: one `<li class="lane" data-lane="…">` per lane, each
 * with a `.chip c-<lane>` whose label is the lane name. The set must be exactly
 * the live lanes — none missing, none retired, none twice — and the chip must
 * agree with its row, or a copy edit could show "MEETING" over the Push row.
 */
function checkLaneList(file, src, lanes) {
  const where = (what) => `${file}: ${what}`;
  const rows = [...src.matchAll(
    /<li class="lane" data-lane="([a-z]+)"><span class="chip c-([a-z]+)">([A-Z]+)<\/span>/g,
  )];
  const listed = [...src.matchAll(/data-lane="([a-z]+)"/g)].map((m) => m[1]);
  if (rows.length !== listed.length) {
    problems.push(where(`${listed.length} data-lane rows but only ${rows.length} in the expected chip shape`));
  }
  for (const [, lane, cls, label] of rows) {
    if (cls !== lane || label.toLowerCase() !== lane) {
      problems.push(where(`lane row ${lane} renders chip c-${cls} "${label}"`));
    }
  }
  const retired = listed.filter((l) => RETIRED.has(l));
  if (retired.length) problems.push(where(`lane list renders a RETIRED lane: ${retired.join(", ")}`));
  const missing = lanes.filter((l) => !listed.includes(l));
  if (missing.length) problems.push(where(`lane list is missing lanes: ${missing.join(", ")}`));
  const dupes = listed.filter((l, i) => listed.indexOf(l) !== i);
  if (dupes.length) problems.push(where(`lane list repeats: ${[...new Set(dupes)].join(", ")}`));
  const unknown = listed.filter((l) => !lanes.includes(l) && !RETIRED.has(l));
  if (unknown.length) problems.push(where(`lane list has lanes the API does not: ${unknown.join(", ")}`));
  // A retired lane as a chip anywhere on the page, not just inside the list.
  const strayChips = [...src.matchAll(/class="chip c-(auto|call)"/g)].map((m) => m[1]);
  if (strayChips.length) problems.push(where(`page renders a RETIRED lane chip: ${strayChips.join(", ")}`));
}

function check(file, lanes) {
  const src = readFileSync(file, "utf8");
  const where = (what) => `${file}: ${what}`;

  const hasList = src.includes('class="lane-list"');
  const hasDemo = src.includes('id="dm-buckets"');
  if (!hasList && !hasDemo) {
    problems.push(where("no lane surface found (.lane-list or the hero demo) — did the lanes move?"));
    return;
  }
  if (hasList) checkLaneList(file, src, lanes);
  if (!hasDemo) return;

  // --- hero demo ------------------------------------------------------
  const buckets = [...src.matchAll(/class="bk" data-t="([a-z]+)"/g)].map((m) => m[1]);
  if (buckets.length === 0) problems.push(where("no .bk buckets found — did the hero demo move?"));

  const missing = lanes.filter((l) => !buckets.includes(l));
  if (missing.length) problems.push(where(`hero buckets are missing lanes: ${missing.join(", ")}`));

  const retiredBuckets = buckets.filter((b) => RETIRED.has(b));
  if (retiredBuckets.length) {
    problems.push(where(`hero renders a RETIRED lane as a bucket: ${retiredBuckets.join(", ")}`));
  }

  // Samples must land in a bucket that exists. This is the one that froze KO.
  const mails = arrayAfter(src, "var mails =");
  if (!mails) problems.push(where("var mails not found"));
  else {
    const tags = [...mails.matchAll(/,\s*'([a-z]+)'\s*\]/g)].map((m) => m[1]);
    const orphans = [...new Set(tags)].filter((t) => !buckets.includes(t));
    if (orphans.length) {
      problems.push(
        where(
          `sample mail tagged with a lane that has no bucket: ${orphans.join(", ")} ` +
            `— the demo throws inside a setTimeout and the counter freezes`,
        ),
      );
    }
  }

  // Totals drive the reduced-motion path, which indexes cells[] directly.
  const totals = src.match(/var totals = \{([^}]*)\}/);
  if (!totals) problems.push(where("var totals not found"));
  else {
    const keys = [...totals[1].matchAll(/(\w+)\s*:/g)].map((m) => m[1]);
    const extra = keys.filter((k) => !buckets.includes(k));
    const absent = buckets.filter((b) => !keys.includes(b));
    if (extra.length) problems.push(where(`totals has keys with no bucket: ${extra.join(", ")}`));
    if (absent.length) problems.push(where(`totals is missing buckets: ${absent.join(", ")}`));
  }

  // --- interactive replica --------------------------------------------
  const tiers = arrayAfter(src, "var TIERS =");
  if (!tiers) problems.push(where("var TIERS not found — did the replica move?"));
  else {
    const ids = [...tiers.matchAll(/id:\s*'([a-z]+)'/g)].map((m) => m[1]);
    const retiredTiers = ids.filter((i) => RETIRED.has(i));
    if (retiredTiers.length) {
      problems.push(where(`replica offers a RETIRED lane: ${retiredTiers.join(", ")}`));
    }
    const missingTiers = lanes.filter((l) => !ids.includes(l));
    if (missingTiers.length) problems.push(where(`replica is missing lanes: ${missingTiers.join(", ")}`));

    const replicaMail = arrayAfter(src, "var mail =");
    if (replicaMail) {
      const used = [...new Set([...replicaMail.matchAll(/t:\s*'([a-z]+)'/g)].map((m) => m[1]))];
      const orphans = used.filter((t) => !ids.includes(t));
      if (orphans.length) {
        problems.push(where(`replica sample uses a lane absent from TIERS: ${orphans.join(", ")}`));
      }
    }
  }
}

/**
 * The video sources are marketing surfaces too, and they drift the same way.
 *
 * `make-assets.py` burns caption strips into the 31-second demo and the
 * 14-second promo; `Promo.tsx` renders the motion-graphics promo's lane badges.
 * Both listed PUSH / QUEUE / SILENT / AUTO for weeks after AUTO was retired,
 * and Promo.tsx captioned its AUTO card "handled for you" — the exact sentence
 * docs/product-vocabulary.md forbids. Nothing could see it: these files produce
 * binaries, so no HTML guard reaches them, and the rendered assets under
 * website/media/ are only regenerated by hand.
 *
 * This checks the sources, which is the part CI can actually hold.
 */
const VIDEO_SOURCES = [
  "scripts/demo-video/make-assets.py",
  "scripts/demo-video/promo-remotion/src/Promo.tsx",
];

function checkVideoSource(file, ids) {
  let src;
  try {
    src = readFileSync(file, "utf8");
  } catch {
    return; // deleted or renamed — not this guard's business
  }
  const where = (msg) => `${file}: ${msg}`;

  // A lane list is any run of lane names joined by " / ", the shape both files
  // use for their caption strips and badge rows.
  for (const m of src.matchAll(/\b((?:PUSH|MEETING|QUEUE|INFO|SILENT|AUTO|CALL)(?:\s*\/\s*(?:PUSH|MEETING|QUEUE|INFO|SILENT|AUTO|CALL))+)/g)) {
    const listed = m[1].split("/").map((x) => x.trim().toLowerCase());
    const retired = listed.filter((t) => RETIRED.has(t));
    if (retired.length) {
      problems.push(where(`caption lists a retired lane: ${retired.join(", ")} in "${m[1]}"`));
    }
    const missing = ids.filter((t) => !listed.includes(t));
    if (missing.length) {
      problems.push(where(`caption lane list is missing: ${missing.join(", ")} in "${m[1]}"`));
    }
  }

  // Promo.tsx builds its badges from a TIERS array of { name: "PUSH", ... }.
  const badges = arrayAfter(src, "const TIERS =");
  if (badges) {
    const named = [...badges.matchAll(/name:\s*"([A-Z]+)"/g)].map((x) => x[1].toLowerCase());
    if (named.length) {
      const retired = named.filter((t) => RETIRED.has(t));
      if (retired.length) problems.push(where(`badge row renders a retired lane: ${retired.join(", ")}`));
      const missing = ids.filter((t) => !named.includes(t));
      if (missing.length) problems.push(where(`badge row is missing: ${missing.join(", ")}`));
    }
  }
}

const lanes = liveLanes();
for (const file of LANDINGS) check(file, lanes);
for (const file of VIDEO_SOURCES) checkVideoSource(file, lanes);

if (problems.length) {
  console.error("::error::website lane drift");
  for (const p of problems) console.error(`✗ ${p}`);
  console.error("");
  console.error("Every landing renders the five live lanes (the .lane-list; older pages a");
  console.error("hero demo plus a replica). Fix it in every language the site ships.");
  console.error("The demo/promo video sources carry the lane names too — see VIDEO_SOURCES.");
  process.exit(1);
}

console.log(
  `✓ website lanes: ${lanes.length} live lanes (${lanes.join(", ")}) consistent across ` +
    `the lane lists (and any hero demo/replica) in ${LANDINGS.length} landings, ` +
    `and in ${VIDEO_SOURCES.length} video sources.`,
);
